import{_ as t,c as r,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Purchase","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/index.md","filePath":"master/supply-chain/purchase/index.md","lastUpdated":1792041590000}'),s={name:"master/supply-chain/purchase/index.md"};function n(i,e,d,l,c,h){return a(),r("div",null,e[0]||(e[0]=[o(`<h1 id="purchase" tabindex="-1">Purchase <a class="header-anchor" href="#purchase" aria-label="Permalink to &quot;Purchase&quot;">​</a></h1><p>Purchase is where you buy goods and services from vendors. You ask a vendor for a price, agree on an order, receive the goods and pay the bill. Aureus keeps every step in one record, so you always know what you ordered, what arrived and what you owe.</p><blockquote><p><strong>In simple words:</strong> Ask the vendor, order, receive, pay.</p></blockquote><h2 id="the-whole-flow" tabindex="-1">The whole flow <a class="header-anchor" href="#the-whole-flow" aria-label="Permalink to &quot;The whole flow&quot;">​</a></h2><p>One document carries the deal from start to end. It is a <strong>Request for Quotation</strong> (RFQ) until you confirm it. After that it is a <strong>Purchase Order</strong>. Both use the prefix <code>PO/</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Need  →  RFQ  →  Send to vendor  →  Confirm order  →  Receive goods  →  Vendor bill  →  Pay</span></span>
<span class="line"><span>          PO/1     RFQ Sent         Purchase Order    Inventory         Finance</span></span></code></pre></div><ul><li><strong>Need:</strong> You run low on a product or a customer order needs it.</li><li><strong>RFQ:</strong> You list the products, quantities and prices you want.</li><li><strong>Send:</strong> You email the RFQ to the vendor as a PDF.</li><li><strong>Confirm:</strong> You accept the deal. Aureus plans a receipt in Inventory.</li><li><strong>Receive:</strong> The warehouse validates the receipt and stock goes up.</li><li><strong>Bill:</strong> You create the vendor bill from what arrived. Finance handles payment.</li></ul><h2 id="settings-that-switch-features-on" tabindex="-1">Settings that switch features on <a class="header-anchor" href="#settings-that-switch-features-on" aria-label="Permalink to &quot;Settings that switch features on&quot;">​</a></h2><p>Some menus and fields appear only after you turn on a setting. Go to <code>Purchase → Settings</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Page</th><th>What it adds</th></tr></thead><tbody><tr><td><strong>Purchase Order Approval</strong></td><td><strong>Manage Orders</strong></td><td>Large orders wait for a manager</td></tr><tr><td><strong>Lock Confirmed Orders</strong></td><td><strong>Manage Orders</strong></td><td>Confirmed orders become read only</td></tr><tr><td><strong>Purchase Agreements</strong></td><td><strong>Manage Orders</strong></td><td>The <strong>Purchase Agreements</strong> menu and the <strong>Agreement</strong> field</td></tr><tr><td><strong>Variants</strong></td><td><strong>Manage Products</strong></td><td><strong>Attributes</strong> menu and product variants</td></tr><tr><td><strong>Unit of Measure</strong></td><td><strong>Manage Products</strong></td><td>The <strong>Unit</strong> column on order lines</td></tr><tr><td><strong>Packagings</strong></td><td><strong>Manage Products</strong></td><td><strong>Packagings</strong> menu and packaging columns</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Receipts need the Inventory app. Without it, an order still works, but no receipt is planned. Vendor bills need the Invoices or Accounting app and a purchase journal.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p><strong>Get started</strong></p><ul><li><a href="./get-started/">Get started</a>: the first-time path.</li><li><a href="./get-started/purchase-settings.html">Purchase settings</a>: every option and what it turns on.</li><li><a href="./get-started/first-steps.html">First steps</a>: one tutorial from a new vendor to a vendor bill.</li></ul><p><strong>Products</strong></p><ul><li><a href="./products/">Products</a>: the purchase side of a product.</li><li><a href="./products/configure-product.html">Configure a product</a>: the Vendors tab and purchase fields.</li><li><a href="./products/vendor-price-lists.html">Vendor price lists</a>: prices by vendor and quantity.</li><li><a href="./products/product-configuration.html">Product configuration</a>: currencies, categories, attributes, packagings, units.</li></ul><p><strong>Orders</strong></p><ul><li><a href="./orders/">Orders</a>: the deal flow and statuses.</li><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a>: create vendors and set their purchase terms.</li><li><a href="./orders/quotations.html">Quotations</a>: create and send an RFQ.</li><li><a href="./orders/purchase-orders.html">Purchase orders</a>: confirm, approve, lock and cancel.</li><li><a href="./../inventories/operations/receipts.html">Receipts</a>: bring the goods in (in the Inventory guide).</li><li><a href="./orders/vendor-bills.html">Vendor bills</a>: bill what you received.</li><li><a href="./orders/purchase-agreements.html">Purchase agreements</a>: blanket orders and templates.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../inventories/">Inventory</a> for receipts and stock.</li><li><a href="./../../finance/vendor-bills/">Vendor bills in Finance</a> for payment.</li><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a> for vendor master data.</li></ul>`,20)]))}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
